// Control flow in posts (I6): loop / if / thread / wait-signal / set-signal instructions (as generated by T7's control
// models) are written in vendor syntax where the language has it, and as a comment + reported warning otherwise.
import { describe, it, expect } from 'vitest';
import { Station } from '../src/core/items/item';
import { Program } from '../src/core/items/program';
import { createRobotFromLibrary } from '../src/core/items/library';
import { compileForPost, getPost } from '../src/posts/index';

function cell() {
  const st = new Station('ctl');
  const robot = st.addChild(createRobotFromLibrary('UR5e'));
  const mk = (name: string, q: number[]) => { const p = st.addChild(new Program(name)); p.setRobot(robot); p.addMoveJ(q); return p; };
  const body = mk('Body', [0, -90, 90, -90, -90, 0]);
  const other = mk('Other', [10, -90, 90, -90, -90, 0]);
  const main = st.addChild(new Program('Main'));
  main.setRobot(robot);
  main.addMoveJ([5, -90, 90, -90, -90, 0]);
  main.addInstruction({ kind: 'loop', count: 3, bodyProgramId: body.id });
  main.addInstruction({ kind: 'if', condition: 'DI_3 == 1', thenProgramId: body.id, elseProgramId: other.id });
  main.addInstruction({ kind: 'if', condition: '3', thenProgramId: other.id });
  main.addInstruction({ kind: 'thread', programId: other.id });
  main.waitSignal('5', 1, 500);
  main.addInstruction({ kind: 'signal', signal: '2', value: 1, wait: false });
  main.addInstruction({ kind: 'loop', count: 0, bodyProgramId: other.id });
  return compileForPost(st, main, { nativeThreads: true });
}
const text = (id: string) => { const c = cell(); const files = getPost(id)!.generate(c, { date: new Date(2026, 9, 25, 12) }); return { c, all: files.map((f) => `#### ${f.name}\n${f.content}`).join('\n').replace(/\r/g, ''), files }; };

describe('control flow in vendor posts', () => {
  it('compileForPost keeps loop / if / thread as structured events and compiles the bodies once', () => {
    const c = cell();
    expect(c.events.filter((e) => e.kind === 'loop').map((e: any) => [e.count, e.body])).toEqual([[3, 'Body'], [0, 'Other']]);
    expect(c.events.find((e) => e.kind === 'if')).toMatchObject({ condition: 'DI_3 == 1', then: 'Body', else: 'Other' });
    expect(c.subprograms.map((s) => s.name).sort()).toEqual(['Body', 'Other']);
    expect(c.events.find((e) => e.kind === 'waitDI')).toMatchObject({ io: '5', value: 1, timeoutMs: 500 });
    expect(c.events.find((e) => e.kind === 'setDO')).toMatchObject({ io: '2', value: 1 });
  });
  it('KUKA KRL: FOR with a declared counter, LOOP, IF/ELSE on $IN', () => {
    const { all, c } = text('KUKA_KRC4');
    const main = all.slice(all.indexOf('#### Main.src'), all.indexOf('#### ', all.indexOf('#### Main.src') + 5) >>> 0 || undefined);
    expect(main.indexOf('DECL INT I_LOOP1')).toBeGreaterThan(main.indexOf('DEF Main ( )'));
    expect(main.indexOf('DECL INT I_LOOP1')).toBeLessThan(main.indexOf('BAS (#INITMOV,0)')); // declarations first
    expect(main).toMatch(/FOR I_LOOP1 = 1 TO 3\n {2}Body\(\)\nENDFOR/);
    expect(main).toMatch(/IF DI_3==TRUE THEN\n {2}Body\(\)\nELSE\n {2}Other\(\)\nENDIF/);
    expect(main).toMatch(/IF \$IN\[3\]==TRUE THEN\n {2}Other\(\)\nENDIF/);
    expect(main).toMatch(/LOOP\n {2}Other\(\)\nENDLOOP/);
    expect(main).toMatch(/\$OUT\[2\]=TRUE/);
    // KRL has no threads: called sequentially and reported
    expect(c.problems.some((p) => /Threads are not supported/.test(p))).toBe(true);
  });
  it('ABB RAPID: FOR / WHILE TRUE / IF-ELSE, sub-programs as PROCs', () => {
    const { all } = text('ABB_RAPID_IRC5');
    expect(all).toMatch(/FOR i1 FROM 1 TO 3 DO\n\t\t {4}Body;\n\t\tENDFOR/);
    expect(all).toMatch(/IF DI_3 = 1 THEN\n\t\t {4}Body;\n\t\tELSE\n\t\t {4}Other;\n\t\tENDIF/);
    expect(all).toMatch(/IF D_IN_3 = 1 THEN\n\t\t {4}Other;\n\t\tENDIF/);
    expect(all).toMatch(/WHILE TRUE DO\n\t\t {4}Other;\n\t\tENDWHILE/);
    expect(all).toContain('WaitDI D_IN_5, 1, \\MaxTime:=0.5;');
    expect(all).toMatch(/PROC Body\(\)[\s\S]*ENDPROC/);
  });
  it('Fanuc TP: FOR/ENDFOR on a register, IF ... THEN/ELSE/ENDIF, RUN for threads', () => {
    const { all } = text('Fanuc_R30iA');
    expect(all).toMatch(/FOR R\[10\]=1 TO 3 ;\n\s+\d+:\s+CALL Body ;\n\s+\d+:\s+ENDFOR ;/);
    expect(all).toMatch(/IF \(DI_3=ON\) THEN ;\n\s+\d+:\s+CALL Body ;\n\s+\d+:\s+ELSE ;\n\s+\d+:\s+CALL Other ;\n\s+\d+:\s+ENDIF ;/);
    expect(all).toMatch(/IF DI\[3\]=ON,CALL Other ;/);
    expect(all).toMatch(/RUN Other ;/);
    expect(all).toMatch(/LBL\[\d+\] ;\n\s+\d+:\s+CALL Other ;\n\s+\d+:\s+JMP LBL\[\d+\] ;/);
  });
  it('Motoman INFORM: counted loop with a label and JUMP, conditional CALL JOB', () => {
    const { all } = text('Motoman');
    expect(all).toMatch(/SET I090 0\n\*L1\nCALL JOB:BODY\nINC I090\nJUMP \*L1 IF I090<3/);
    expect(all).toMatch(/CALL JOB:OTHER IF IN#\(3\)=ON/);
  });
  it('URScript: while loops, if/else, real threads', () => {
    const { all } = text('Universal_Robots');
    expect(all).toMatch(/loop_i1 = 0\n\s+while \(loop_i1 < 3\):\n\s+Body\(\)\n\s+loop_i1 = loop_i1 \+ 1\n\s+end/);
    expect(all).toMatch(/if \(DI_3 == True\):\n\s+Body\(\)\n\s+else:\n\s+Other\(\)\n\s+end/);
    expect(all).toMatch(/thread Thread_Other\(\):\n\s+Other\(\)\n\s+end/);
    expect(all).toMatch(/thrd_Other = run Thread_Other\(\)/);
    expect(all).toMatch(/while \(True\):\n\s+Other\(\)\n\s+end/);
  });
  it('Kawasaki AS and Comau PDL2: FOR loops and IF blocks', () => {
    const k = text('Kawasaki').all;
    expect(k).toMatch(/FOR loop_i = 1 TO 3\n\s+CALL Body\n\s+END/);
    expect(k).toMatch(/IF SIG\(DI_3\) THEN\n\s+CALL Body\n\s+ELSE\n\s+CALL Other\n\s+END/);
    expect(k).toMatch(/PCEXECUTE Other/);
    const c = text('Comau_C5G').all;
    expect(c).toMatch(/FOR \$INT_VAR\[1\] := 1 TO 3 DO\n\s+R_Body\n\s+ENDFOR/);
    expect(c).toMatch(/IF DI_3 = ON THEN\n\s+R_Body\n\s+ELSE\n\s+R_Other\n\s+ENDIF/);
    expect(c).toMatch(/REPEAT\n\s+R_Other\n\s+UNTIL FALSE/);
  });
  it('posts without control flow write a comment, call the body once and report it', () => {
    const { all, c } = text('Mecademic');
    expect(all).toMatch(/\/\/ loop 3x: Body/);
    expect(c.problems.some((p) => /Loops are not supported by this post/.test(p))).toBe(true);
    expect(c.problems.some((p) => /IF is not supported by this post/.test(p))).toBe(true);
  });
});
